describe('Stale Data Invalidation After Form Submission', () => {
  const apiUrl = 'http://localhost:3000/api';
  const formUrl = 'http://localhost:3000/form';

  beforeEach(() => {
    cy.visit(formUrl);
    cy.intercept('GET', `${apiUrl}/data`, {
      statusCode: 200,
      body: { id: 1, name: 'Old Data', timestamp: Date.now() }
    }).as('initialData');
    cy.intercept('POST', `${apiUrl}/submit`, {
      statusCode: 200,
      body: { success: true, message: 'Form submitted successfully' }
    }).as('formSubmit');
    cy.intercept('GET', `${apiUrl}/data`, {
      statusCode: 200,
      body: { id: 1, name: 'Updated Data', timestamp: Date.now() + 1000 }
    }).as('refreshedData');
  });

  it('should invalidate stale data and fetch fresh data after successful form submission', () => {
    // Load initial data
    cy.get('[data-cy=load-data-btn]').click();
    cy.wait('@initialData');
    cy.get('[data-cy=data-display]').should('contain', 'Old Data');

    // Submit form
    cy.get('[data-cy=form-input]').type('New Value');
    cy.get('[data-cy=submit-btn]').click();
    cy.wait('@formSubmit');

    // Verify stale data is invalidated and fresh data is fetched
    cy.get('[data-cy=data-display]').should('contain', 'Updated Data');
    cy.get('[data-cy=cache-status]').should('contain', 'Cache invalidated');
  });

  it('should handle form submission failure and preserve existing data', () => {
    // Load initial data
    cy.get('[data-cy=load-data-btn]').click();
    cy.wait('@initialData');
    cy.get('[data-cy=data-display]').should('contain', 'Old Data');

    // Intercept failed submission
    cy.intercept('POST', `${apiUrl}/submit`, {
      statusCode: 400,
      body: { success: false, message: 'Form submission failed' }
    }).as('failedSubmit');

    // Attempt form submission
    cy.get('[data-cy=form-input]').type('Invalid Value');
    cy.get('[data-cy=submit-btn]').click();
    cy.wait('@failedSubmit');

    // Verify data is not invalidated on failure
    cy.get('[data-cy=data-display]').should('contain', 'Old Data');
    cy.get('[data-cy=error-message]').should('be.visible');
    cy.get('[data-cy=cache-status]').should('contain', 'Cache preserved');
  });

  it('should handle concurrent form submissions and invalidate data only once', () => {
    // Load initial data
    cy.get('[data-cy=load-data-btn]').click();
    cy.wait('@initialData');

    // Submit multiple forms rapidly
    cy.get('[data-cy=form-input]').first().type('Value 1');
    cy.get('[data-cy=submit-btn]').first().click();

    cy.get('[data-cy=form-input]').last().type('Value 2');
    cy.get('[data-cy=submit-btn]').last().click();

    cy.wait('@formSubmit');
    cy.wait('@formSubmit');

    // Verify data is refreshed and cache invalidation count is correct
    cy.get('[data-cy=data-display]').should('contain', 'Updated Data');
    cy.get('[data-cy=invalidation-count]').should('contain', '1');
  });
});
